import { existsSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'bun:test';
import { NESTOR_BUILTIN_TOOL_NAMES, normalizeNestorToolCall } from '../tool-schema.ts';
import snapshot from './fixtures/backend-tool-contract.json';

// The fixture is a mechanical snapshot of the backend's own `tools.go` (generated by
// `scripts/nestor-tool-contract-snapshot.mjs`), NOT a hand-written restatement of it: this
// suite proves every backend-declared key is accepted and carried, and that ONE undeclared
// key throws. It does NOT prove the inverse direction (a key we accept that the backend
// dropped/renamed) — that lives in `tool-schema.test.ts`'s pre-contract negative controls,
// which pin the OLD shapes as rejected. The snapshot is the UNION across agent modes; see
// its `note`.

interface ContractProperty {
  type: string;
  items?: { type: string };
  minItems?: number;
  maxItems?: number;
}

interface ContractTool {
  name: string;
  strict: boolean;
  required: string[];
  properties: Record<string, ContractProperty>;
}

const contract = snapshot as unknown as {
  source: string;
  note: string;
  tools: ContractTool[];
};

const REPO_ROOT = join(import.meta.dir, '..', '..', '..', '..', '..', '..', '..');
const BACKEND_TOOLS_GO = join(REPO_ROOT, contract.source);

function sampleValue(key: string, property: ContractProperty): unknown {
  switch (property.type) {
    case 'string':
      return `sample-${key}`;
    case 'boolean':
      return true;
    case 'array': {
      expect(property.items?.type, `${key} item type`).toBe('string');
      const length = Math.max(property.minItems ?? 1, 1);
      return Array.from({ length }, (_unused, index) => `choice-${index + 1}`);
    }
    default:
      // A new JSON-Schema type in the backend snapshot must be handled deliberately,
      // never sampled by guess.
      throw new Error(`Unhandled snapshot property type for ${key}: ${property.type}`);
  }
}

function buildArgs(tool: ContractTool, keys: readonly string[]): Record<string, unknown> {
  const args: Record<string, unknown> = {};
  for (const key of keys) {
    const property = tool.properties[key];
    expect(property, `${tool.name}.${key} declared`).toBeDefined();
    args[key] = sampleValue(key, property!);
  }
  return args;
}

function normalize(name: string, args: Record<string, unknown>) {
  return normalizeNestorToolCall({
    id: `snapshot-${name}`,
    index: 0,
    name,
    arguments: JSON.stringify(args),
  });
}

describe('Nestor backend tool contract snapshot', () => {
  it('covers exactly the builtin vocabulary this adapter implements', () => {
    expect(contract.tools.map(tool => tool.name).sort())
      .toEqual([...NESTOR_BUILTIN_TOOL_NAMES].sort());
  });

  // Strict:true on every backend tool definition is what makes a closed key set legitimate:
  // the model cannot send a property the schema does not declare.
  it('records every builtin as Strict, which is what licenses the closed key set', () => {
    for (const tool of contract.tools) {
      expect(tool.strict, tool.name).toBe(true);
    }
  });

  it.each(contract.tools.map(tool => [tool.name, tool] as const))(
    'accepts %s with only the backend-required keys',
    (name, tool) => {
      const call = normalize(name, buildArgs(tool, tool.required));

      expect(call.kind).toBe('builtin');
      expect(call.builtinName as string | undefined).toBe(name);
      for (const key of tool.required) {
        expect(Object.keys(call.args)).toContain(key);
      }
    },
  );

  it.each(contract.tools.map(tool => [tool.name, tool] as const))(
    'accepts and carries every property %s declares',
    (name, tool) => {
      const keys = Object.keys(tool.properties);
      const call = normalize(name, buildArgs(tool, keys));

      expect(call.kind).toBe('builtin');
      expect(Object.keys(call.args).sort()).toEqual([...keys].sort());
    },
  );

  it.each(contract.tools.map(tool => [tool.name, tool] as const))(
    'rejects %s the moment one undeclared key rides along',
    (name, tool) => {
      const args = { ...buildArgs(tool, tool.required), not_in_tools_go: 'x' };

      expect(() => normalize(name, args)).toThrow('Unknown Nestor tool argument: not_in_tools_go');
    },
  );

  // Drift gate for developers who have the pinned backend checkout: the committed fixture
  // must still be what the generator produces from `tools.go`. `.references/` is gitignored,
  // so on CI (and any machine without it) this skips — the committed fixture is then the
  // contract of record, exactly as the tasks above use it.
  it.skipIf(!existsSync(BACKEND_TOOLS_GO))(
    'is still what the generator produces from the pinned backend tools.go',
    () => {
      const result = Bun.spawnSync(['node', join('scripts', 'nestor-tool-contract-snapshot.mjs'), '--check'], {
        cwd: REPO_ROOT,
      });

      expect(result.stderr.toString() + result.stdout.toString()).toContain('up to date');
      expect(result.exitCode).toBe(0);
    },
  );
});
